# fixed gain example (no adptation)

ft = 20 # simulation time in seconds
dt = 0.005 # time step in seconds

x = 1 # initial state
w = 5 # unknown weight

#k = 5.1 # fixed gain
#k = 6 
k = 10

x_rec = [] # state record
u_rec = [] # control record
t_rec = [] # time record

for t in range(int(ft/dt)):
    time = t*dt
    u = -k*x # control law
    x = x + dt*(w*x + u) # system dynamics

    # record data
    x_rec.append(x)
    u_rec.append(u)
    t_rec.append(time)

# plot results
