# Point reference adaptive gain example

ft = 20 # simulation time in seconds
dt = 0.005 # time step in seconds

x = 0 # initial state
what = 0
w = 1 # unknown weight

alp = 2 # nominal control gain
gamma = 50 # adaptation gain

x_rec = [] # state record
u_rec = [] # control record
t_rec = [] # time record
w_rec = [] # weight record

for t in range(int(ft/dt)):
    time = t*dt
    xr = 1 # reference point
    if time <= 5 :
        c = 1
    else :
        c = -1
    e = x - c # tracking error
    u = -alp*e - what*x # control law
    what = what + dt*gamma*x*e # weight adaptation
    x = x + dt*(w*x + u) # system dynamics

