# reference model adaptive gain example

ft = 20 # simulation time in seconds
dt = 0.005 # time step in seconds

x = 0 # initial state
xr = 0 # reference model state
what = 0
w = 1 # unknown weight

alp = 2 # nominal control gain
gamma = 50 # adaptation gain

x_rec = [] # state record
