w_rec = [] # weight record

for t in range(int(ft/dt)):
    time = t*dt

    if time <= 5 :
        c = 1
    else :
        c = -1

    xr = xr + dt*(-alp*(xr - c)) # reference model update
    u = -alp*(x-c) - what*x # control law
    what = what + dt*gamma*x*(x - xr) # weight adaptation
