# %% [cell 4] code
# Projection operator example
import numpy as np
import matplotlib.pyplot as plt

ft = 10 # simulation time in seconds
dt = 0.005 # time step in seconds

x = 0 # initial state
xr = 0 # reference model state
what = 0 # initial weight

alp = 2 # nominal control gain
gam = 50 # adaptation gain
wbd = 5 # weight bound max and min
eps = 0.2 # projection tolerance

x_rec = [] # state record
xr_rec = [] # reference model state record
u_rec = [] # control record
t_rec = [] # time record
w_rec = [] # weight record
w_true_rec = [] # true weight record

for t in range(int(ft/dt)):
    time = t*dt
    w = 1.5 + 0.25 * np.cos(0.5*time) # time-varying unknown weight

    if time <= 5 :
        c = 1
    else :
        c = -1

    u = -alp*(x - c) - what*x # control law
    xr = xr + dt*(-alp*(xr - c)) # reference model update

    # weight adaptation with projection
    PR = x*(x - xr)
    if what > wbd - eps and PR > 0:
        PR = (wbd - what)/eps * PR
    elif what < -wbd + eps and PR < 0:
        PR = (what + wbd)/eps * PR
    what = what + dt*gam*PR

    x = x + dt*(w*x + u) # system dynamics

    # record data
    x_rec.append(x)
    xr_rec.append(xr)
    u_rec.append(u)
    t_rec.append(time)
    w_rec.append(what)
    w_true_rec.append(w)

# plot results
import matplotlib.pyplot as plt

plt.figure(figsize=(10,8))
plt.subplot(3,1,1)
plt.plot(t_rec, x_rec, label='State x')
plt.plot(t_rec, xr_rec, label='Reference Model x_r', linestyle='--')
plt.axhline(y=1, color='r', linestyle='--', label='Reference c=1')
plt.axhline(y=-1, color='g', linestyle='--', label='Reference c=-1')
plt.axvline(x=5, color='k', linestyle=':', alpha=0.5)
plt.title('State over Time')
plt.xlabel('Time [s]')
plt.ylabel('State x')
plt.legend()
plt.grid()

plt.subplot(3,1,2)
plt.plot(t_rec, u_rec)
plt.title('Control Input over Time')
plt.xlabel('Time [s]')
plt.ylabel('Control u')
plt.grid()

plt.subplot(3,1,3)
plt.plot(t_rec, w_rec)
plt.plot(t_rec, w_true_rec, label='True Weight w', linestyle='--')
plt.title('Estimated Weight over Time')
plt.xlabel('Time [s]')
plt.ylabel('Estimated Weight ŵ')
plt.grid()

plt.tight_layout()
