# Neuro-adaptive control example 6 neurons with sigma modification and Performance recovery
import numpy as np
import matplotlib.pyplot as plt

ft = 20 # simulation time in seconds
dt = 0.005 # time step in seconds

x = 0 # initial state
xr = 0 # reference model + recovery signal initial state
xri = 0 # reference model initial state
psi = 0 # time domain performance recovery signal initial state
what = np.zeros((6,1)) # initial weight

alp = 2 # nominal control gain
gam = 50 # adaptation gain
sigma = 0.2 # sigma modification gain
lam = 5 # performance recovery gain

def rbf(x, d1, d2):
    return np.exp(-d1*abs(x - d2)**2)
    
x_rec = [] # state record
xr_rec = [] # reference model state record
xri_rec = [] # ideal reference model state record
u_rec = [] # control record
t_rec = [] # time record
w_rec = [] # weight record
ua_rec = [] # neural network control record
delta_rec = [] # nonlinearity record
v_rec = [] # recovery control record
psi_rec = [] # performance recovery signal record


for t in range(int(ft/dt)):
    time = t*dt
    
    delta = 1 + x**2 + np.sin(x)*x**3 + np.cos(x)*x**4 # unknown nonlinearity

    if time <= 5 :
        c = 1
    elif 5 < time <= 10 :
        c = -1
    elif 10 < time <= 15 :
        c = 1
    else :
        c = -1

    theta = np.zeros_like(what)
    for i in range(len(what)):
        theta[i] = rbf(x, 0.1, -5 + i*2) # RBFs centered at -5, -3, -1, 1, 3, 5

    un = -alp*(x - c) # nominal control
    ua = -what.T @ theta # neural network control
    psi = psi + dt*(-lam*(psi - (x-xr))) # performance recovery signal update
    v = lam*psi - (alp + lam)*(x - xr) # recovery control term
    u = un + ua + v # total control input + the recovery term
    xr = xr + dt*(-alp*(xr - c) + v ) # reference model update
    xri = xri + dt*(-alp*(xri - c)) # ideal reference model update

    what = what + dt*(gam*(theta*(x - xr) - sigma*what)) # weight adaptation with sigma leakage

    x = x + dt*(delta + u) # system dynamics

    # record data
    x_rec.append(float(x))
    xr_rec.append(float(xr))
    xri_rec.append(float(xri))
    u_rec.append(float(u))
    t_rec.append(time)
    w_rec.append(what.flatten())
    ua_rec.append(float(ua))
    delta_rec.append(float(delta))
    v_rec.append(float(v))
    psi_rec.append(float(psi))

# plot results
plt.figure(figsize=(10,15))
plt.subplot(5,1,1)
plt.plot(t_rec, x_rec, label='State x')
plt.plot(t_rec, xri_rec, label='Reference Model x_r', linestyle='--')
plt.plot(t_rec, xr_rec, label='Performance Recovery Model x_{r+}', linestyle=':')
plt.axhline(y=1, color='r', linestyle='--', label='Reference c=1')
plt.axhline(y=-1, color='g', linestyle='--', label='Reference c=-1')
plt.axvline(x=5, color='k', linestyle=':', alpha=0.5)
plt.axvline(x=10, color='k', linestyle=':', alpha=0.5)
plt.axvline(x=15, color='k', linestyle=':', alpha=0.5)
plt.title('State over Time')
plt.xlabel('Time [s]')
plt.ylabel('State x')
plt.legend()
plt.grid()

plt.subplot(5,1,2)
plt.plot(t_rec, u_rec)
plt.title('Control Input over Time')
plt.xlabel('Time [s]')
plt.ylabel('Control u')
plt.grid()

plt.subplot(5,1,3)
for i in range(len(what)):
    w_i = [w[i] for w in w_rec]
    plt.plot(t_rec, w_i, label=f'Weight ŵ[{i}]')
plt.title('Estimated Weights over Time')
plt.xlabel('Time [s]')
plt.ylabel('Estimated Weights ŵ')
plt.legend()
plt.grid()

plt.subplot(5,1,4)
plt.plot(t_rec, [-u for u in ua_rec], label='Estimated Nonlinearity (-u_a)')
plt.plot(t_rec, delta_rec, label='True Nonlinearity delta', linestyle='--')
plt.title('Nonlinearity Estimation vs True Nonlinearity')
plt.xlabel('Time [s]')
plt.ylabel('Value')
plt.legend()
plt.grid()

plt.subplot(5,1,5)
plt.plot(t_rec, v_rec, label='Recovery Control v')
plt.plot(t_rec, psi_rec, label='Performance Recovery Signal ψ', linestyle='--')
plt.title('Recovery Control over Time')
plt.xlabel('Time [s]')
plt.ylabel('Value')
plt.legend()
plt.grid()

plt.tight_layout()
