# %% [cell 12] code
# Mass-spring-damper system with adaptive control 2 dimensions
import numpy as np
import control as ct
import matplotlib.pyplot as plt

ft = 40 # simulation time in seconds
dt = 0.005 # time step in seconds

mass = 5.0 # mass
alpha = 2.5 # Spring constant
beta = 1.0 # Damping coefficient
A = np.array([[0, 1], [0, 0]]) # A matrix of the system
B = np.array([[0], [1]]) # B matrix of the system
Lam = np.array([[1/mass]]) # Lambda
# True weight vector - represents the true parameters -alpha and -beta
# Uncertainty is W0.T @ x = -alpha*x - beta*v
W0 = np.array([[ -alpha ], [ -beta ]]) 
x = np.array([[0.], [0.]]) # initial state

K1, S, E = ct.lqr(A, B, np.eye(2), np.eye(1)*0.1) # LQR gain
# Note: K1 from ct.lqr might be matrix or array, ensure shape
K1 = np.asarray(K1)

# Feedforward gain
# Ar = A - B K1
Ar = A - B @ K1 # reference model A matrix
# K2 = -1 / (C Ar^-1 B) for C = [1 0]
C = np.array([[1, 0]])
K2 = -1.0 / (C @ np.linalg.inv(Ar) @ B).item()

Br = B * K2 # reference model B matrix
xr = np.array([[0.], [0.]]) # reference model initial state

gam = 10 # adaptation gain
# Solve Lyapunov for Ar^T P + P Ar = -I
P = ct.lyap(Ar.T, np.eye(2)) 
What = np.zeros((3,1)) # initial weight estimate - matches regressor size

x_rec = [] # state record
xr_rec = [] # reference model state record
u_rec = [] # control record
t_rec = [] # time record
w_rec = [] # weight record

for t in range(int(ft/dt)):
    time = t*dt

    if time <= 10 :
        c = 1
    elif 10 < time <= 20 :
        c = -1
    elif 20 < time <= 30 :
        c = 1
    else :
        c = -1

    
    un = -K1 @ x + K2 * c # nominal control   
    # Regressor is just the state [position, velocity**3, un]
    phi = np.vstack((x[0], x[1]**3, un))
    phi_r = np.vstack((xr[0], xr[1]**3))
    # Adaptive control law
    ua = -What.T @ phi 
    u = un + ua 


    # Reference model update
    xr = xr + dt*(Ar @ xr + Br * c)
    e = x - xr
    # Weights adaptation update
    What = What + dt*(gam * phi @ (e.T @ P @ B)) 


    # System dynamics (True Equation)
    # xdot = A x + B Lam (u + W0.T @ phi)
    # This corresponds to mass*xdd = u - alpha*x - beta*v
    x = x + dt*(A @ x + B @ Lam @ (u + W0.T @ phi_r)) 

    # record data
    x_rec.append(x.flatten())
    xr_rec.append(xr.flatten())
    u_rec.append(u.item())
    t_rec.append(time)
    w_rec.append(What.flatten())

# plot results
plt.figure(figsize=(10,12))
plt.subplot(4,1,1)
plt.plot(t_rec, [x[0] for x in x_rec], label='Position x[0]')
plt.plot(t_rec, [xr[0] for xr in xr_rec], label='Reference Model x_r[0]', linestyle='--')
plt.axhline(y=1, color='r', linestyle='--', label='Reference c=1')
plt.axhline(y=-1, color='g', linestyle='--', label='Reference c=-1')
plt.axvline(x=10, color='k', linestyle=':', alpha=0.5)
plt.axvline(x=20, color='k', linestyle=':', alpha=0.5)
plt.axvline(x=30, color='k', linestyle=':', alpha=0.5)
plt.title('Position over Time')
plt.xlabel('Time [s]')
plt.ylabel('Position x[0]')
plt.legend()
plt.grid()
plt.subplot(4,1,2)
plt.plot(t_rec, [x[1] for x in x_rec], label='Velocity x[1]')
plt.plot(t_rec, [xr[1] for xr in xr_rec], label='Reference Model x_r[1]', linestyle='--')
plt.axhline(y=0, color='k', linestyle='--')
plt.axvline(x=10, color='k', linestyle=':', alpha=0.5)
plt.axvline(x=20, color='k', linestyle=':', alpha=0.5)
plt.axvline(x=30, color='k', linestyle=':', alpha=0.5)
plt.title('Velocity over Time')
plt.xlabel('Time [s]')
plt.ylabel('Velocity x[1]')
plt.legend()
plt.grid()

plt.subplot(4,1,3)
plt.plot(t_rec, u_rec)
plt.title('Control Input over Time')
plt.xlabel('Time [s]')
plt.ylabel('Control u')
plt.grid()

plt.subplot(4,1,4)
for i in range(len(What)):
    w_i = [w[i] for w in w_rec]
    plt.plot(t_rec, w_i, label=f'Weight Ŵ[{i}]')
plt.hlines([-alpha, -beta], t_rec[0], t_rec[-1], colors='r', linestyles='--', label='True Weights')
plt.title('Estimated Weights over Time')
plt.xlabel('Time [s]')
plt.ylabel('Estimated Weights Ŵ')
plt.legend()
plt.grid()

plt.tight_layout()
