# Mass-spring-damper system with adaptive control 2 dimensions 
# with 5 neurons RBF for each state plus a bias term
import numpy as np
import control as ct
import matplotlib.pyplot as plt

ft = 40 # simulation time in seconds
dt = 0.005 # time step in seconds

A = np.array([[0, 1], [0, 0]]) # A matrix of the system (Double Integrator)
B = np.array([[0], [1]]) # B matrix of the system
Lam = np.array([[0.75]]) # True Lambda (Input Gain)
x = np.array([[0.], [0.]]) # initial state

# LQR Design for Reference Model
K1, S, E = ct.lqr(A, B, np.eye(2), 0.1) 
K1 = np.asarray(K1)

# Reference Model Matrices: Ar = A - B*K1
Ar = A - B @ K1 
# Feedforward Gain K2 to ensure DC gain is 1
C = np.array([[1, 0]])
K2 = -1.0 / (C @ np.linalg.inv(Ar) @ B).item()
Br = B * K2 

xr = np.array([[0.], [0.]]) # reference model initial state

gam = 10 # adaptation gain
sig = 0.1 # sigma modification gain
P = ct.lyap(Ar.T, np.eye(2)) # Solve Lyapunov Equation

# Neural Network (RBF) Setup
# 12 Weights: 1 Bias + 5 for Position + 5 for Velocity + 1 for Input (Lambda adaptation)
What = np.zeros((12,1)) 

def rbf(x, c, width):
    return np.exp(-width * abs(x - c)**2)

x_rec = [] 
xr_rec = []
u_rec = [] 
t_rec = [] 
w_rec = [] 
unc_rec = [] 
ua_rec = []

for t in range(int(ft/dt)):
    time = t*dt

    # Reference Command
    if time <= 10 :
        c = 0.5
    elif 10 < time <= 20 :
        c = -0.5
    elif 20 < time <= 30 :
        c = 0.5
    else :
        c = -0.5
    
    un = -K1 @ x + K2 * c # nominal control

    # Construct Regressor (theta)
    theta = np.zeros((12, 1))
    
    # 0: Bias term
    theta[0] = 1.0 
    
    # 1-5: Position RBFs (Centered at 2, 1, 0, -1, -2 to match MATLAB)
    for i in range(5):
        center = 2.0 - i  # 2, 1, 0, -1, -2
        theta[i+1] = rbf(x[0], center, 0.25)
        
    # 6-10: Velocity RBFs (Centered at 2, 1, 0, -1, -2 to match MATLAB)
    for i in range(5):
        center = 2.0 - i  # 2, 1, 0, -1, -2
